UPDATE tb_group_extends
archived = #{extends.archived}, archived_file = #{extends.archivedFile}, archived_attachxxx_file = #{extends.archivedAttachxxxFile}, archived_user_id = #{extends.archivedUserId}, archived_time = #{extends.archivedTime}
WHERE group_id = #{groupId}

mapper.select:
SELECT tge.id, tgc.user_id, tgc.group_id, tcg.group_name as groupName,tge.archived, tcg.create_time as gmtCreated, tge.archived_time,tcg.avatar_img as avatarImg, COALESCE(tag_agg.tags, '') as tagName, 1 as is_care, tge.group_type as groupType, tcg.owner_id as ownerId, tcg.user_ids as members, tge.archived_user_id as archivedUserId FROM tb_group_care tgc LEFT JOIN tb_group_extends tge ON tge.group_id = tgc.group_id LEFT JOIN tb_create_group tcg ON tge.group_id = tcg.group_id LEFT JOIN LATERAL ( SELECT GROUP_CONCAT(tag.name SEPARATOR ',') as tags FROM tb_group_tag tgt LEFT JOIN tb_label tag ON tgt.tag_id = tag.id WHERE tgt.group_id = tge.group_id AND tgt.is_deleted = 0 ) tag_agg ON TRUE
AND ( tcg.user_names LIKE CONCAT('%', #{keywords}, '%') OR tcg.group_name LIKE CONCAT('%', #{keywords}, '%') OR DATE_FORMAT(tcg.create_time, '%Y/%m/%d') LIKE CONCAT('%', #{keywords}, '%') OR DATE_FORMAT(tcg.create_time, '%Y/%c/%e') LIKE CONCAT('%', #{keywords}, '%') OR DATE_FORMAT(tge.archived_time, '%Y/%m/%d') LIKE CONCAT('%', #{keywords}, '%') OR DATE_FORMAT(tge.archived_time, '%Y/%c/%e') LIKE CONCAT('%', #{keywords}, '%') OR tcg.department_name LIKE CONCAT('%', #{keywords}, '%') OR EXISTS (SELECT 1 FROM tr_tasks_group ttg LEFT JOIN tb_tasks tt ON ttg.task_id = tt.id WHERE ttg.group_id = tge.group_id AND tt.name LIKE CONCAT('%', #{keywords}, '%')) OR EXISTS (SELECT 1 FROM tr_police_ticket_group tptg LEFT JOIN tb_police_ticket tpt ON tptg.ticket_id = tpt.id WHERE tptg.group_id = tge.group_id AND tpt.name LIKE CONCAT('%', #{keywords}, '%')) )
AND tge.group_type = #{groupType}
AND tge.archived_time >= STR_TO_DATE(CONCAT(#{archivedTime}, '-01'), '%Y-%m-%d') AND tge.archived_time < DATE_ADD(STR_TO_DATE(CONCAT(#{archivedTime}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH)
AND tge.archived IN
#{archived}
AND tgc.user_id = #{userId}
AND ( tcg.user_ids LIKE CONCAT('%', #{userId}, '%')
OR
tcg.user_ids LIKE CONCAT('%', #{postId}, '%')
)
AND tcg.department_id IN
#{orgId}
ORDER BY
tge.archived_time DESC, tcg.create_time DESC
tcg.create_time DESC

SELECT CONCAT(YEAR(tge.archived_time), '-',LPAD(MONTH(tge.archived_time), 2, '0')) AS yearMonth, COUNT(DISTINCT tge.group_id) AS count FROM tb_group_care tgc LEFT JOIN tb_group_extends tge ON tge.group_id = tgc.group_id LEFT JOIN tb_create_group tcg ON tge.group_id = tcg.group_id WHERE tge.archived = 2 AND tgc.user_id = #{userId}
AND ( tcg.group_name LIKE CONCAT('%', #{keywords}, '%') OR tcg.user_names LIKE CONCAT('%', #{keywords}, '%') OR DATE_FORMAT(tcg.create_time, '%Y/%m/%d') LIKE CONCAT('%', #{keywords}, '%') OR DATE_FORMAT(tcg.create_time, '%Y/%c/%e') LIKE CONCAT('%', #{keywords}, '%') OR DATE_FORMAT(tge.archived_time, '%Y/%m/%d') LIKE CONCAT('%', #{keywords}, '%') OR DATE_FORMAT(tge.archived_time, '%Y/%c/%e') LIKE CONCAT('%', #{keywords}, '%') OR tcg.department_name LIKE CONCAT('%', #{keywords}, '%') OR EXISTS (SELECT 1 FROM tr_tasks_group ttg LEFT JOIN tb_tasks tt ON ttg.task_id = tt.id WHERE ttg.group_id = tge.group_id AND tt.name LIKE CONCAT('%', #{keywords}, '%')) OR EXISTS (SELECT 1 FROM tr_police_ticket_group tptg LEFT JOIN tb_police_ticket tpt ON tptg.ticket_id = tpt.id WHERE tptg.group_id = tge.group_id AND tpt.name LIKE CONCAT('%', #{keywords}, '%')) )
AND ( tcg.user_ids LIKE CONCAT('%', #{userId}, '%')
OR
tcg.user_ids LIKE CONCAT('%', #{postId}, '%')
)
AND tcg.department_id IN
#{orgId}
AND archived_time IS NOT NULL GROUP BY yearMonth ORDER BY yearMonth DESC

select tge.group_id as groupId, tcg.group_name as groupName, tag_agg.tags as tagName, tcg.department_name as departmentName, tge.archived_time as archivedTime,tge.archived_file as archivedFile,concat(tt.name,tpt.name) as taskName, tiu.name as archiveUserName from tb_group_extends tge left join tb_create_group tcg on tge.group_id = tcg.group_id left join tr_tasks_group ttg on tge.group_id = ttg.group_id left join tb_tasks tt on ttg.task_id = tt.id LEFT JOIN tr_police_ticket_group tptg on tge.group_id= tptg.group_id left join tb_police_ticket tpt on tptg.ticket_id=tpt.id left join icp_res.tb_im_user tiu on tge.archived_user_id = tiu.id LEFT JOIN LATERAL ( SELECT GROUP_CONCAT(tag.name SEPARATOR ',') as tags FROM tb_group_tag tgt LEFT JOIN tb_label tag ON tgt.tag_id = tag.id WHERE tgt.group_id = tge.group_id AND tgt.is_deleted = 0 ) tag_agg ON TRUE where tge.archived = 2
and tge.group_id in
#{groupId}

SELECT DISTINCT tge.id, tge.group_id, tcg.group_name as groupName, tge.archived, tcg.avatar_img as avatarImg, tcg.create_time as gmtCreated, tge.archived_time, tge.group_type as groupType, tcg.owner_id as ownerId, tcg.user_ids as members, tcg.source as source FROM tb_group_extends tge LEFT JOIN tb_create_group tcg ON tge.group_id = tcg.group_id
tcg.existed = 1
AND tcg.owner_id = #{userId}
AND ( tcg.user_ids LIKE CONCAT('%', #{userId}, '%')
OR
tcg.user_ids LIKE CONCAT('%', #{postId}, '%')
)
AND tcg.user_ids NOT LIKE CONCAT('%', #{userId}, '%')
AND
tcg.user_ids NOT LIKE CONCAT('%', #{postId}, '%')
AND tcg.owner_id != #{userId}
AND tcg.department_id IN
#{orgId}
AND 1 = 0
AND ( tcg.owner_id = #{userId} OR tcg.user_ids LIKE CONCAT('%', #{userId}, '%')
OR
tcg.user_ids LIKE CONCAT('%', #{postId}, '%')
OR tcg.department_id IN
#{orgId}
)
AND tge.group_type = #{groupType}
AND tcg.source = #{createType}
AND tge.archived IN (0, 1, 2)
GROUP BY tge.id, tge.group_id, tcg.group_name, tge.archived, tcg.avatar_img, tcg.create_time, tge.archived_time, tge.group_type, tcg.owner_id, tcg.user_ids, tcg.source ORDER BY tcg.create_time DESC

SELECT SUM(CASE WHEN tge.group_type = 1 AND tge.archived = 0 THEN 1 ELSE 0 END) as normalGroupUnarchivedCount, SUM(CASE WHEN tge.group_type = 1 AND tge.archived IN (1, 2) THEN 1 ELSE 0 END) as normalGroupArchivedCount, SUM(CASE WHEN tge.group_type = 2 AND tge.archived = 0 THEN 1 ELSE 0 END) as coopGroupUnarchivedCount, SUM(CASE WHEN tge.group_type = 2 AND tge.archived IN (1, 2) THEN 1 ELSE 0 END) as coopGroupArchivedCount FROM ( SELECT DISTINCT tge.id, tge.group_type, tge.archived FROM tb_group_extends tge LEFT JOIN tb_create_group tcg ON tge.group_id = tcg.group_id
tcg.existed = 1 AND ( tcg.owner_id = #{userId} OR tcg.user_ids LIKE CONCAT('%', #{userId}, '%')
OR
tcg.user_ids LIKE CONCAT('%', #{postId}, '%')
) AND tge.archived IN (0, 1, 2)
) tge
